package com.crowdin.client.core.http.impl.json;

import com.crowdin.client.core.http.exceptions.HttpBadRequestException;
import com.crowdin.client.core.http.exceptions.HttpException;
import com.crowdin.client.projectsgroups.model.Project;
import com.crowdin.client.sourcefiles.model.ExportOptions;
import com.crowdin.client.sourcefiles.model.FileInfo;
import com.crowdin.client.sourcefiles.model.ImportOptions;
import com.crowdin.client.stringtranslations.model.LanguageTranslations;
import org.junit.Assert;
import org.junit.Test;

import java.util.Date;

public class JacksonJsonTransformerTest {

    @Test
    public void parseHttpExceptionTest() throws Exception {
        JacksonJsonTransformer transformer = new JacksonJsonTransformer();
        String errorJson = "{\"statusCode\":400, \"message\": \"Invalid request\"}";
        HttpException exception = transformer.parse(errorJson, HttpException.class);
        Assert.assertEquals(400, exception.getStatusCode());
        Assert.assertEquals("Invalid request", exception.getMessage());
    }

    @Test
    public void parseHttpBadRequestExceptionTest() throws Exception {
        JacksonJsonTransformer transformer = new JacksonJsonTransformer();
        String errorJson = "{\"statusCode\":400, \"message\": \"Invalid request\"}";
        HttpBadRequestException exception = transformer.parse(errorJson, HttpBadRequestException.class);
        Assert.assertEquals(400, exception.getStatusCode());
        Assert.assertEquals("Invalid request", exception.getMessage());
    }

    @Test
    public void parseProjectTest() throws Exception {
        JacksonJsonTransformer transformer = new JacksonJsonTransformer();
        String projectJson = "{\"id\":1, \"name\": \"test project\"}";
        Project project = transformer.parse(projectJson, Project.class);
        Assert.assertEquals(1, project.getId().longValue());
        Assert.assertEquals("test project", project.getName());
    }

    @Test
    public void convertProjectTest() throws Exception {
        JacksonJsonTransformer transformer = new JacksonJsonTransformer();
        Project project = new Project();
        project.setId(1L);
        project.setName("test project");
        String projectJson = transformer.convert(project);
        Assert.assertTrue(projectJson.contains("\"id\":1"));
        Assert.assertTrue(projectJson.contains("\"name\":\"test project\""));
    }

    @Test
    public void parseLanguageTranslationsTest() throws Exception {
        JacksonJsonTransformer transformer = new JacksonJsonTransformer();
        String langsJson = "{\"languageId\":\"en\", \"translations\": {\"key\": \"value\"}}";
        LanguageTranslations translations = transformer.parse(langsJson, LanguageTranslations.class);
        Assert.assertEquals("en", translations.getLanguageId());
        Assert.assertEquals("value", translations.getTranslations().get("key"));
    }
}
